21	/****************************************************************************
22	 * Pre-processor Definitions
23	 ****************************************************************************/
24	
25	/* Logical flash layout.  CPU-visible XIP addresses are FLASH_XIP_BASE plus
26	 * the logical offsets below.  CRC-packed physical offsets use the 34/32
27	 * expansion because all partition boundaries are 32-byte aligned.
28	 */
29	
30	#define BK7258_FLASH_XIP_BASE            0x02000000u
31	#define BK7258_BOOT_FLASH_OFFSET         0x00000000u
32	#define BK7258_BOOT_FLASH_SIZE           0x00010000u
33	#define BK7258_CP_FLASH_OFFSET           0x00010000u
34	#define BK7258_CP_FLASH_SIZE             0x000f0000u
35	#define BK7258_DATA_FLASH_OFFSET         0x00100000u
36	#define BK7258_DATA_FLASH_SIZE           0x00100000u
37	#define BK7258_AP_FLASH_OFFSET           0x00200000u
38	#define BK7258_AP_FLASH_SIZE             0x00200000u
39	
40	#define BK7258_CP_FLASH_ADDR             \
41	  (BK7258_FLASH_XIP_BASE + BK7258_CP_FLASH_OFFSET)
42	#define BK7258_AP_FLASH_ADDR             \
43	  (BK7258_FLASH_XIP_BASE + BK7258_AP_FLASH_OFFSET)
44	
45	#define BK7258_CRC_PHYSICAL_OFFSET(n)    (((n) / 32u) * 34u)
46	#define BK7258_CP_PHYSICAL_OFFSET        \
47	  BK7258_CRC_PHYSICAL_OFFSET(BK7258_CP_FLASH_OFFSET)
48	#define BK7258_DATA_PHYSICAL_OFFSET      \
49	  BK7258_CRC_PHYSICAL_OFFSET(BK7258_DATA_FLASH_OFFSET)
50	#define BK7258_AP_PHYSICAL_OFFSET        \
51	  BK7258_CRC_PHYSICAL_OFFSET(BK7258_AP_FLASH_OFFSET)
52	
53	/* The 640 KiB SRAM window is split between two independent NuttX kernels.
54	 * The top 4 KiB page is excluded from both linkers and remains shared.
55	 */
56	
57	#define BK7258_SRAM_BASE                 0x28000000u
58	#define BK7258_SRAM_SIZE                 0x000a0000u
59	#define BK7258_CP_RAM_BASE               0x28000000u
60	#define BK7258_CP_RAM_SIZE               0x00050000u
61	#define BK7258_AP_RAM_BASE               0x28050000u
62	#define BK7258_AP_RAM_SIZE               0x0004f000u
63	#define BK7258_SHARED_RAM_BASE           0x2809f000u
64	#define BK7258_SHARED_RAM_SIZE           0x00001000u
65	
66	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
67	#  define BK7258_CPU2_BOOT_STACK_SIZE    CONFIG_ARCH_INTERRUPTSTACK
68	#else
69	#  define BK7258_CPU2_BOOT_STACK_SIZE    0x00000400u
70	#endif
71	
72	#define BK7258_CPU2_BOOT_STACK_TOP       BK7258_SHARED_RAM_BASE
73	#define BK7258_CPU2_BOOT_STACK_BASE      \
74	  (BK7258_CPU2_BOOT_STACK_TOP - BK7258_CPU2_BOOT_STACK_SIZE)
75	
76	/* Preserve the N8-A names for the AP-UP probe implementation. */
77	
78	#define BK7258_CPU2_PROBE_STACK_SIZE     BK7258_CPU2_BOOT_STACK_SIZE
79	#define BK7258_CPU2_PROBE_STACK_TOP      BK7258_CPU2_BOOT_STACK_TOP
80	#define BK7258_CPU2_PROBE_STACK_BASE     BK7258_CPU2_BOOT_STACK_BASE
81	
82	#define BK7258_CP_HEAP_END               \
83	  (BK7258_CP_RAM_BASE + BK7258_CP_RAM_SIZE - 4u)
84	#define BK7258_AP_HEAP_END               \
85	  (BK7258_CPU2_BOOT_STACK_BASE - 4u)
86	
87	/* The SDK uses a per-core DTCM word as its local core-ID cell.  AP logical
88	 * core 0 writes zero there and reports SoC physical CPU1 as local + 1.
89	 */
90	
91	#define BK7258_LOCAL_CORE_ID_ADDR        0x20000000u
92	#define BK7258_AP_PHYSICAL_ID_OFFSET     1u
93	
94	/* Raw system and mailbox registers used by the minimal Stage N7 wrapper. */
95	
96	#define BK7258_SYS_CPU1_CONTROL          0x44010014u
97	#define BK7258_SYS_CPU1_RESET            (1u << 0)
98	#define BK7258_SYS_CPU1_POWER_DOWN       (1u << 1)
99	#define BK7258_SYS_CPU1_RXEVT_SEL        (1u << 5)
100	#define BK7258_SYS_CPU1_BOOT_MASK        0xffffff00u
101	
102	#define BK7258_SYS_CPU2_CONTROL          0x44010018u
103	#define BK7258_SYS_CPU2_RESET            (1u << 0)
104	#define BK7258_SYS_CPU2_POWER_DOWN       (1u << 1)
105	#define BK7258_SYS_CPU2_HALT             (1u << 3)
106	#define BK7258_SYS_CPU2_RXEVT_SEL        (1u << 5)
107	#define BK7258_SYS_CPU2_BOOT_MASK        0xffffff00u
108	
109	#define BK7258_MBOX0_BASE                0x41000000u /* CPU0 -> CPU1 */
110	#define BK7258_MBOX1_BASE                0x41020000u /* CPU1 -> CPU0 */
111	#define BK7258_MBOX_CLKRST_OFFSET        0x08u
112	#define BK7258_MBOX_READY_OFFSET         0x10u
113	#define BK7258_MBOX_CLEAR_OFFSET         0x14u
114	#define BK7258_MBOX_SENDER_OFFSET        0x18u
115	#define BK7258_MBOX_RECEIVER_OFFSET      0x1cu
116	#define BK7258_MBOX_PARAM0_OFFSET        0x20u
117	#define BK7258_MBOX_PARAM1_OFFSET        0x24u
118	#define BK7258_MBOX_PARAM2_OFFSET        0x28u
119	#define BK7258_MBOX_PARAM3_OFFSET        0x2cu
120	#define BK7258_MBOX_BOX0_BIT             (1u << 0)
121	
122	#define BK7258_AP_BOOT_STATE_MAGIC       0x53425041u /* "APBS" */
123	#define BK7258_AP_BOOT_STATE_VERSION     1u
124	#define BK7258_AP_DOORBELL_MAGIC         0x524f4f44u /* "DOOR" */
125	#define BK7258_AP_DEFAULT_TIMEOUT_MS     3000u
126	#define BK7258_AP_RESTART_DELAY_MS       6u
127	
128	/* Keep the 0x80-byte boot-state ABI stable.  A fault-only extension lives
129	 * immediately after it in the otherwise unused shared page.
130	 */
131	
132	#define BK7258_AP_FAULT_STATE_OFFSET     0x00000080u
133	#define BK7258_AP_FAULT_STATE_MAGIC      0x544c4641u /* "AFLT" */
134	#define BK7258_AP_FAULT_STATE_VERSION    1u
135	
136	/* CPU0 owns a separate record so an AP-side peripheral or mailbox operation
137	 * that faults CP cannot overwrite the AP exception evidence.
138	 */
139	
140	#define BK7258_CP_FAULT_STATE_OFFSET     0x00000100u
141	#define BK7258_CP_FAULT_STATE_MAGIC      0x544c4643u /* "CFLT" */
142	#define BK7258_CP_FAULT_STATE_VERSION    1u
143	
144	/* Physical CPU2 shared state.  N8-A uses it for the freestanding probe;
145	 * N8-B1 preserves the ABI while publishing the NuttX secondary-bootstrap
146	 * contract and the still-offline scheduler mask.
147	 */
148	
149	#define BK7258_CPU2_PROBE_STATE_OFFSET   0x00000180u
150	#define BK7258_CPU2_PROBE_STATE_MAGIC    0x32555043u /* "CPU2" */
151	#define BK7258_CPU2_PROBE_STATE_VERSION  1u
152	#define BK7258_CPU2_PROBE_TIMEOUT_MS     1000u
153	#define BK7258_CPU2_PROBE_STOP_TIMEOUT_MS 100u
