349	static_assert(BK7258_CP_FLASH_OFFSET + BK7258_CP_FLASH_SIZE ==
350	              BK7258_DATA_FLASH_OFFSET,
351	              "CP flash must end at the LittleFS boundary");
352	static_assert(BK7258_DATA_FLASH_OFFSET + BK7258_DATA_FLASH_SIZE ==
353	              BK7258_AP_FLASH_OFFSET,
354	              "AP flash must start after LittleFS");
355	static_assert(BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE ==
356	              BK7258_SHARED_RAM_BASE,
357	              "AP RAM must end at the shared page");
358	static_assert(sizeof(struct bk7258_ap_boot_state_s) ==
359	              BK7258_AP_FAULT_STATE_OFFSET,
360	              "AP boot-state ABI must remain 0x80 bytes");
361	static_assert(BK7258_AP_FAULT_STATE_OFFSET +
362	              sizeof(struct bk7258_ap_fault_state_s) <=
363	              BK7258_CP_FAULT_STATE_OFFSET,
364	              "AP and CP fault states overlap");
365	static_assert(BK7258_CP_FAULT_STATE_OFFSET +
366	              sizeof(struct bk7258_cp_fault_state_s) <=
367	              BK7258_CPU2_PROBE_STATE_OFFSET,
368	              "CP fault state overlaps the CPU2 probe state");
369	static_assert(sizeof(struct bk7258_cpu2_probe_state_s) == 0x80,
370	              "CPU2 probe-state ABI must remain 0x80 bytes");
371	static_assert(BK7258_CPU2_PROBE_STATE_OFFSET +
372	              sizeof(struct bk7258_cpu2_probe_state_s) <=
373	              BK7258_SHARED_RAM_SIZE,
374	              "CPU2 probe state exceeds the shared page");
375	static_assert(BK7258_CPU2_PROBE_STACK_BASE >= BK7258_AP_RAM_BASE,
376	              "CPU2 probe stack must remain in AP-owned RAM");
377	static_assert(BK7258_CPU2_PROBE_STACK_TOP == BK7258_SHARED_RAM_BASE,
378	              "CPU2 probe stack must end at the shared-page boundary");
