2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/ap/
3	 * bk7258_ap_smp.c
4	 *
5	 * SPDX-License-Identifier: Apache-2.0
6	 *
7	 * N8-B1 physical CPU2 secondary bootstrap.  NuttX creates the logical CPU1
8	 * IDLE TCB and calls up_cpu_start(), but this first SMP stage deliberately
9	 * parks CPU2 before nx_idle_trampoline().  The scheduler remains restricted
10	 * to logical CPU0 until the bidirectional IPI path is available.
11	 ****************************************************************************/
