73	static inline volatile uint32_t *bk7258_cpu2_control(void)
74	{
75	  return (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
76	}
77	
78	static void bk7258_cpu2_hold_reset(
79	  volatile struct bk7258_cpu2_probe_state_s *state)
80	{
81	  volatile uint32_t *control = bk7258_cpu2_control();
82	  uint32_t value = *control;
83	
84	  value &= ~BK7258_SYS_CPU2_RESET;
85	  *control = value;
86	  __asm volatile ("dsb sy; isb sy" ::: "memory");
87	
88	  if (state != NULL)
89	    {
90	      state->control_after = value;
91	      __asm volatile ("dmb sy" ::: "memory");
92	    }
93	}
94	
95	static int bk7258_cpu2_wait(uint32_t wanted, uint32_t timeout_ms)
96	{
97	  volatile struct bk7258_cpu2_probe_state_s *state =
98	    bk7258_cpu2_probe_state();
99	  uint32_t current;
100	  uint32_t elapsed;
101	
102	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
103	    {
104	      current = state->state;
105	      __asm volatile ("dmb sy" ::: "memory");
106	      if (current == wanted)
107	        {
108	          return OK;
109	        }
110	
111	      if (current == BK7258_CPU2_PROBE_STATE_FAILED)
112	        {
113	          return -EIO;
114	        }
115	
116	      up_mdelay(1);
117	    }
118	
119	  return -ETIMEDOUT;
120	}
