122	static void bk7258_cpu2_fail(uint32_t error)
123	{
124	  volatile struct bk7258_cpu2_probe_state_s *state =
125	    bk7258_cpu2_probe_state();
126	
127	  state->secondary_ready = 0;
128	  state->error = error;
129	  __asm volatile ("dmb sy" ::: "memory");
130	  state->state = BK7258_CPU2_PROBE_STATE_FAILED;
131	  __asm volatile ("dmb sy" ::: "memory");
132	}
