134	static void bk7258_cpu2_note_missing_ipi(void)
135	{
136	  volatile struct bk7258_cpu2_probe_state_s *state =
137	    bk7258_cpu2_probe_state();
138	
139	  if (state->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
140	      state->version == BK7258_CPU2_PROBE_STATE_VERSION)
141	    {
142	      state->smp_call_requests++;
143	      if (state->error == BK7258_CPU2_PROBE_ERROR_NONE)
144	        {
145	          state->error = BK7258_CPU2_PROBE_ERROR_IPI_UNAVAILABLE;
146	        }
147	
148	      __asm volatile ("dmb sy; sev" ::: "memory");
149	    }
150	}
