152	static void __attribute__((noinline, noreturn, used))
153	bk7258_ap_secondary_bootstrap(void)
154	{
155	  volatile struct bk7258_cpu2_probe_state_s *state =
156	    bk7258_cpu2_probe_state();
157	  uint32_t control;
158	  uint32_t msp;
159	
160	  __asm volatile ("mrs %0, msp" : "=r" (msp));
161	  __asm volatile ("mrs %0, control" : "=r" (control));
162	
163	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
164	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
165	  state->runtime_vtor = BK7258_SCB_VTOR;
166	  state->runtime_msp = msp;
167	  state->control = control;
168	  state->boot_count++;
169	  __asm volatile ("dmb sy" ::: "memory");
170	
171	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
172	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
173	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
174	    {
175	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
176	      goto parked;
177	    }
178	
179	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
180	  __asm volatile ("dmb sy" ::: "memory");
181	
182	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
183	        BK7258_CPU2_LOCAL_CORE_ID ||
184	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
185	    {
186	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
187	      goto parked;
188	    }
189	
190	  if (state->runtime_vtor !=
191	      (uint32_t)(uintptr_t)__vector_core1_table)
192	    {
193	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
194	      goto parked;
195	    }
196	
197	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
198	      msp > BK7258_CPU2_BOOT_STACK_TOP)
199	    {
200	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
201	      goto parked;
202	    }
203	
204	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
205	      state->idle_stack_base >= state->idle_stack_top ||
206	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
207	    {
208	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
209	      goto parked;
210	    }
211	
212	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
213	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
214	  state->online_mask = BK7258_AP_PRIMARY_MASK;
215	  state->secondary_ready = 1;
216	  __asm volatile ("dmb sy" ::: "memory");
217	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
218	  __asm volatile ("dmb sy; sev" ::: "memory");
219	
220	  for (; ; )
221	    {
222	      __asm volatile ("dmb sy" ::: "memory");
223	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
224	        {
225	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
226	          state->secondary_ready = 0;
227	          __asm volatile ("dmb sy" ::: "memory");
228	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
229	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
230	          __asm volatile ("dmb sy; sev" ::: "memory");
231	          goto parked;
232	        }
233	
234	      state->heartbeat++;
235	      __asm volatile ("dmb sy; wfe" ::: "memory");
236	    }
237	
238	parked:
239	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
240	  for (; ; )
241	    {
242	      __asm volatile ("wfe");
243	    }
244	}
