246	static void __attribute__((naked, noreturn, used))
247	bk7258_ap_secondary_reset(void)
248	{
249	  __asm volatile
250	    (
251	      "cpsid i\n"
252	      "movs r0, #0\n"
253	      "msr control, r0\n"
254	      "msr basepri, r0\n"
255	      "msr faultmask, r0\n"
256	      "ldr r0, =0x20000000\n"
257	      "movs r1, #1\n"
258	      "str r1, [r0]\n"
259	      "ldr r0, =__vector_core1_table\n"
260	      "ldr r1, =0xe000ed08\n"
261	      "str r0, [r1]\n"
262	      "dsb sy\n"
263	      "isb sy\n"
264	      "b bk7258_ap_secondary_bootstrap\n"
265	    );
266	}
