268	static void __attribute__((noinline, noreturn, used))
269	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
270	{
271	  volatile struct bk7258_cpu2_probe_state_s *state =
272	    bk7258_cpu2_probe_state();
273	  uintptr_t frame = (uintptr_t)stack;
274	  uint32_t error;
275	
276	  state->fault_exception = exception;
277	  state->fault_hfsr = BK7258_SCB_HFSR;
278	  state->fault_cfsr = BK7258_SCB_CFSR;
279	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
280	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
281	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
282	
283	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
284	      frame >= BK7258_CPU2_BOOT_STACK_BASE &&
285	      frame <= BK7258_CPU2_BOOT_STACK_TOP -
286	               BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
287	    {
288	      const volatile uint32_t *regs =
289	        (const volatile uint32_t *)frame;
290	
291	      state->fault_lr = regs[5];
292	      state->fault_pc = regs[6];
293	      state->fault_xpsr = regs[7];
294	    }
295	
296	  error = exception == 2u ?
297	    BK7258_CPU2_PROBE_ERROR_NMI :
298	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
299	  bk7258_cpu2_fail(error);
300	
301	  for (; ; )
302	    {
303	      __asm volatile ("wfe");
304	    }
305	}
