307	static void __attribute__((naked, noreturn, used))
308	bk7258_ap_secondary_fault_entry(void)
309	{
310	  __asm volatile
311	    (
312	      "tst lr, #4\n"
313	      "ite eq\n"
314	      "mrseq r0, msp\n"
315	      "mrsne r0, psp\n"
316	      "mrs r1, ipsr\n"
317	      "b bk7258_ap_secondary_fault_handler\n"
318	    );
319	}
