343	int up_cpu_idlestack(int cpu, struct tcb_s *tcb, size_t stack_size)
344	{
345	  int ret;
346	
347	  if (cpu != BK7258_AP_SECONDARY_CPU || tcb == NULL)
348	    {
349	      return -EINVAL;
