361	int up_cpu_start(int cpu)
362	{
363	  volatile struct bk7258_cpu2_probe_state_s *state =
364	    bk7258_cpu2_probe_state();
365	  volatile uint32_t *control = bk7258_cpu2_control();
366	  struct tcb_s *tcb;
367	  uintptr_t idle_base;
368	  uintptr_t idle_top;
369	  uint32_t generation;
370	  uint32_t value;
371	  int ret;
372	
373	  if (cpu != BK7258_AP_SECONDARY_CPU)
374	    {
375	      return -EINVAL;
376	    }
377	
378	  bk7258_cpu2_hold_reset(state);
379	  up_mdelay(1);
380	
381	  generation = bk7258_ap_boot_state()->generation;
382	  if (generation == 0)
383	    {
384	      generation = 1;
385	    }
386	
387	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
388	  state->version = BK7258_CPU2_PROBE_STATE_VERSION;
389	  state->size = sizeof(*state);
390	  state->generation = generation;
391	  state->command = BK7258_CPU2_PROBE_COMMAND_START;
392	  state->state = BK7258_CPU2_PROBE_STATE_STARTING;
393	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
394	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
395	  state->vector = (uint32_t)(uintptr_t)__vector_core1_table;
396	  state->initial_msp = BK7258_CPU2_BOOT_STACK_TOP;
397	  state->secondary_entry =
398	    (uint32_t)(uintptr_t)bk7258_ap_secondary_bootstrap;
399	  state->online_mask = BK7258_AP_PRIMARY_MASK;
400	
401	  tcb = current_task(cpu);
402	  if (tcb == NULL || tcb->stack_base_ptr == NULL ||
403	      tcb->adj_stack_size == 0)
404	    {
405	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
406	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
407	      return -ENOMEM;
408	    }
409	
410	  idle_base = (uintptr_t)tcb->stack_base_ptr;
411	  idle_top = idle_base + tcb->adj_stack_size;
412	  state->idle_stack_base = (uint32_t)idle_base;
413	  state->idle_stack_top = (uint32_t)idle_top;
414	
415	  if (idle_base < BK7258_AP_RAM_BASE || idle_base >= idle_top ||
416	      idle_top > BK7258_CPU2_BOOT_STACK_BASE)
417	    {
418	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
419	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
420	      return -ENOMEM;
421	    }
422	
423	  value = *control;
424	  state->control_before = value;
425	  value &= ~(BK7258_SYS_CPU2_RESET |
426	             BK7258_SYS_CPU2_POWER_DOWN |
427	             BK7258_SYS_CPU2_HALT |
428	             BK7258_SYS_CPU2_RXEVT_SEL |
429	             BK7258_SYS_CPU2_BOOT_MASK);
430	  value |= BK7258_SYS_CPU2_RXEVT_SEL;
431	  value |= state->vector & BK7258_SYS_CPU2_BOOT_MASK;
432	  *control = value;
433	  __asm volatile ("dsb sy; isb sy" ::: "memory");
434	
435	  state->control_after = value;
436	  __asm volatile ("dmb sy" ::: "memory");
437	  state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
438	  __asm volatile ("dmb sy" ::: "memory");
439	
440	  value |= BK7258_SYS_CPU2_RESET;
441	  *control = value;
442	  state->control_after = value;
443	  __asm volatile ("dsb sy; sev" ::: "memory");
444	
445	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SECONDARY_READY,
446	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
447	  if (ret < 0)
448	    {
449	      bk7258_cpu2_hold_reset(state);
450	      if (state->state != BK7258_CPU2_PROBE_STATE_FAILED)
451	        {
452	          bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_TIMEOUT);
453	        }
454	    }
455	
456	  return ret;
457	}
