459	int up_send_smp_sched(int cpu)
460	{
461	  if (cpu == up_cpu_index())
462	    {
463	      return OK;
464	    }
465	
466	  if (cpu != BK7258_AP_SECONDARY_CPU)
467	    {
468	      return -EINVAL;
469	    }
470	
471	  bk7258_cpu2_note_missing_ipi();
472	  return -ENOSYS;
473	}
