475	void up_send_smp_call(cpu_set_t cpuset)
476	{
477	  int cpu;
478	  int self = up_cpu_index();
479	
480	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
481	    {
482	      if ((cpuset & ((cpu_set_t)1u << cpu)) != 0 && cpu != self)
483	        {
484	          (void)up_send_smp_sched(cpu);
485	        }
486	    }
487	}
488	
489	int bk7258_ap_smp_secondary_stop(uint32_t timeout_ms)
490	{
491	  volatile struct bk7258_cpu2_probe_state_s *state =
492	    bk7258_cpu2_probe_state();
493	  int ret = OK;
494	
495	  if (timeout_ms == 0)
496	    {
497	      timeout_ms = BK7258_CPU2_PROBE_STOP_TIMEOUT_MS;
498	    }
499	
500	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
501	      state->version != BK7258_CPU2_PROBE_STATE_VERSION)
502	    {
503	      ret = -EIO;
504	    }
505	  else if (state->state == BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
506	           state->state == BK7258_CPU2_PROBE_STATE_BOOTSTRAP ||
507	           state->state == BK7258_CPU2_PROBE_STATE_STARTING)
508	    {
509	      state->command = BK7258_CPU2_PROBE_COMMAND_STOP;
510	      __asm volatile ("dmb sy; sev" ::: "memory");
511	      ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
512	                             timeout_ms);
513	    }
514	  else if (state->state == BK7258_CPU2_PROBE_STATE_FAILED)
515	    {
516	      ret = -EIO;
517	    }
518	
519	  bk7258_cpu2_hold_reset(state);
520	  state->secondary_ready = 0;
521	  __asm volatile ("dmb sy" ::: "memory");
522	
523	  if (ret < 0 && state->state != BK7258_CPU2_PROBE_STATE_FAILED)
524	    {
525	      bk7258_cpu2_fail(ret == -ETIMEDOUT ?
526	        BK7258_CPU2_PROBE_ERROR_TIMEOUT :
527	        BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
528	    }
529	
530	  return ret;
531	}
