47	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
48	{
49	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
50	  __asm volatile ("dsb sy" ::: "memory");
51	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
