59	  uint32_t event = BK7258_AP_EVENT_NONE;
60	
61	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
62	       BK7258_MBOX_BOX0_BIT) != 0)
63	    {
64	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
65	          BK7258_AP_DOORBELL_MAGIC)
66	        {
67	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
68	        }
