79	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
80	
81	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
82	       BK7258_MBOX_BOX0_BIT) != 0)
