99	static int bk7258_ap_validate_runtime(void)
100	{
101	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
102	  void *test;
103	  uint32_t msp;
104	
105	  __asm volatile ("mrs %0, msp" : "=r"(msp));
106	
107	  state->runtime_vtor    = BK7258_SCB_VTOR;
108	  state->runtime_msp     = msp;
109	  state->clock_hz        = bk7258_clockdiag_current_cpu_hz();
110	  state->systick_ctrl    = BK7258_SYSTICK_CTRL;
111	  state->systick_reload  = BK7258_SYSTICK_RELOAD;
112	  state->systick_current = BK7258_SYSTICK_CURRENT;
113	  state->heap_start      = (uint32_t)g_idle_topstack;
114	  state->heap_end        = BK7258_AP_HEAP_END;
115	  state->ram_start       = BK7258_AP_RAM_BASE;
116	  state->ram_end         = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
117	  state->flash_start     = BK7258_AP_FLASH_ADDR;
118	  state->flash_end       = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
119	
120	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR != 0 ||
121	      state->physical_core_id != 1)
122	    {
123	      return BK7258_AP_ERROR_BAD_CORE_ID;
124	    }
125	
126	  if (state->runtime_vtor < BK7258_AP_RAM_BASE ||
127	      state->runtime_vtor >= BK7258_SHARED_RAM_BASE ||
128	      (state->runtime_vtor & 0x1ffu) != 0)
129	    {
130	      return BK7258_AP_ERROR_BAD_VTOR;
131	    }
132	
133	  if ((state->systick_ctrl &
134	       (BK7258_SYSTICK_ENABLE | BK7258_SYSTICK_TICKINT)) !=
135	      (BK7258_SYSTICK_ENABLE | BK7258_SYSTICK_TICKINT) ||
136	      state->systick_reload == 0)
137	    {
138	      return BK7258_AP_ERROR_BAD_SYSTICK;
139	    }
140	
141	  test = kmm_malloc(64);
142	  if (test == NULL)
143	    {
144	      return BK7258_AP_ERROR_HEAP;
145	    }
146	
147	  memset(test, 0xa5, 64);
148	  state->heap_test = (uint32_t)(uintptr_t)test;
149	  kmm_free(test);
150	  return BK7258_AP_ERROR_NONE;
151	}
