153	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
154	static int bk7258_ap_validate_secondary_bootstrap(void)
155	{
156	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
157	    bk7258_cpu2_probe_state();
158	
159	  __asm volatile ("dmb sy" ::: "memory");
160	
161	  if (cpu2->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
162	      cpu2->version != BK7258_CPU2_PROBE_STATE_VERSION ||
163	      cpu2->size != sizeof(struct bk7258_cpu2_probe_state_s) ||
164	      cpu2->generation != bk7258_ap_boot_state()->generation ||
165	      cpu2->state != BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
166	      cpu2->error != BK7258_CPU2_PROBE_ERROR_NONE ||
167	      cpu2->secondary_ready != 1 ||
168	      cpu2->online_mask != 1 ||
169	      cpu2->local_core_id != 1 ||
170	      cpu2->physical_core_id != 2 ||
171	      cpu2->runtime_vtor != cpu2->vector ||
172	      cpu2->runtime_msp <= BK7258_CPU2_BOOT_STACK_BASE ||
173	      cpu2->runtime_msp > BK7258_CPU2_BOOT_STACK_TOP ||
174	      cpu2->idle_stack_base < BK7258_AP_RAM_BASE ||
175	      cpu2->idle_stack_base >= cpu2->idle_stack_top ||
176	      cpu2->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
177	    {
178	      return BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
179	    }
180	
181	  return BK7258_AP_ERROR_NONE;
182	}
183	#endif
