185	/****************************************************************************
186	 * Public Functions
187	 ****************************************************************************/
188	
189	int bk7258_ap_main(int argc, char *argv[])
190	{
191	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
192	  uint32_t event;
193	  int error;
194	  int ret;
195	
196	  (void)argc;
197	  (void)argv;
198	
199	  if (state->magic != BK7258_AP_BOOT_STATE_MAGIC ||
200	      state->version != BK7258_AP_BOOT_STATE_VERSION ||
201	      state->size != sizeof(struct bk7258_ap_boot_state_s))
202	    {
203	      state->state = BK7258_AP_STATE_FAILED;
204	      state->error = BK7258_AP_ERROR_BAD_BOOT_STATE;
205	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
206	      goto parked;
207	    }
208	
209	  error = bk7258_ap_validate_runtime();
210	  if (error != BK7258_AP_ERROR_NONE)
211	    {
212	      state->state = BK7258_AP_STATE_FAILED;
213	      state->error = (uint32_t)error;
214	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
215	      goto parked;
216	    }
217	
218	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
219	  error = bk7258_ap_validate_secondary_bootstrap();
220	  if (error != BK7258_AP_ERROR_NONE)
221	    {
222	      state->state = BK7258_AP_STATE_FAILED;
223	      state->error = (uint32_t)error;
224	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
225	      goto parked;
226	    }
227	#else
228	  ret = bk7258_cpu2_probe_start(BK7258_CPU2_PROBE_TIMEOUT_MS);
229	  if (ret < 0)
230	    {
231	      state->state = BK7258_AP_STATE_FAILED;
232	      state->error = BK7258_AP_ERROR_CPU2_PROBE;
233	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
234	      goto parked;
235	    }
236	#endif
237	
238	  state->error      = BK7258_AP_ERROR_NONE;
239	  state->last_event = BK7258_AP_EVENT_READY;
240	  state->state      = BK7258_AP_STATE_READY;
241	  __asm volatile ("dmb sy" ::: "memory");
242	  bk7258_ap_mbox_send(BK7258_AP_EVENT_READY);
243	
244	  for (; ; )
245	    {
246	      event = bk7258_ap_mbox_receive();
247	      if (event != BK7258_AP_EVENT_NONE)
248	        {
249	          state->last_event = event;
250	        }
251	
252	      if (event == BK7258_AP_EVENT_STOP ||
253	          state->command == BK7258_AP_COMMAND_STOP)
254	        {
255	          state->state = BK7258_AP_STATE_STOPPING;
256	          __asm volatile ("dmb sy" ::: "memory");
257	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
258	          ret = bk7258_ap_smp_secondary_stop(
259	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
260	#else
261	          ret = bk7258_cpu2_probe_stop(
262	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
263	#endif
264	          if (ret < 0)
265	            {
266	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
267	              state->error = BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
268	#else
269	              state->error = BK7258_AP_ERROR_CPU2_PROBE;
270	#endif
271	              state->state = BK7258_AP_STATE_FAILED;
272	              state->last_event = BK7258_AP_EVENT_FAILED;
273	              bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
274	              break;
275	            }
276	
277	          state->state = BK7258_AP_STATE_STOPPED;
278	          state->last_event = BK7258_AP_EVENT_STOPPED;
279	          bk7258_ap_mbox_send(BK7258_AP_EVENT_STOPPED);
280	          break;
281	        }
282	
283	      state->heartbeat++;
284	      __asm volatile ("dmb sy; sev" ::: "memory");
285	      nxsig_usleep(BK7258_AP_HEARTBEAT_US);
286	    }
287	
288	parked:
289	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
290	  for (; ; )
291	    {
292	      __asm volatile ("wfe");
293	    }
294	
295	  return 0;
296	}
