72	static uint32_t apctl_u32(const char *value, uint32_t fallback)
73	{
74	  char *end;
75	  unsigned long parsed;
76	
77	  if (value == NULL)
78	    {
79	      return fallback;
80	    }
81	
82	  parsed = strtoul(value, &end, 0);
83	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
84	    {
85	      return fallback;
86	    }
87	
88	  return (uint32_t)parsed;
89	}
