108	         " MSP(init/run)=%08" PRIx32 "/%08" PRIx32 "\n",
109	         state.local_core_id, state.physical_core_id,
110	         state.initial_vtor, state.runtime_vtor,
111	         state.initial_msp, state.runtime_msp);
