131	             " MSP(init/run)=%08" PRIx32 "/%08" PRIx32 "\n",
132	             cpu2.local_core_id, cpu2.physical_core_id, cpu2.vector,
133	             cpu2.runtime_vtor, cpu2.initial_msp, cpu2.runtime_msp);
134	      printf("CPU2 control=%08" PRIx32
135	             " SYS(before/after)=%08" PRIx32 "/%08" PRIx32 "\n",
136	             cpu2.control, cpu2.control_before, cpu2.control_after);
137	
138	      if (cpu2.secondary_entry != 0 || cpu2.secondary_ready != 0 ||
139	          cpu2.idle_stack_base != 0 || cpu2.idle_stack_top != 0)
140	        {
141	          printf("CPU2 bootstrap entry=%08" PRIx32
142	                 " idle=%08" PRIx32 "..%08" PRIx32
143	                 " ready=%" PRIu32 " online=%08" PRIx32
144	                 " calls=%" PRIu32 " boots=%" PRIu32 "\n",
145	                 cpu2.secondary_entry, cpu2.idle_stack_base,
146	                 cpu2.idle_stack_top, cpu2.secondary_ready,
147	                 cpu2.online_mask, cpu2.smp_call_requests,
148	                 cpu2.boot_count);
149	        }
150	
151	      if (cpu2.fault_exception != 0)
152	        {
153	          printf("CPU2 fault exception=%" PRIu32
154	                 " HFSR/CFSR=%08" PRIx32 "/%08" PRIx32
155	                 " PC/LR/xPSR=%08" PRIx32 "/%08" PRIx32
156	                 "/%08" PRIx32 "\n",
157	                 cpu2.fault_exception, cpu2.fault_hfsr,
158	                 cpu2.fault_cfsr, cpu2.fault_pc, cpu2.fault_lr,
