170	static void apctl_usage(void)
171	{
172	  printf("usage: apctl start|stop|restart|status [timeout_ms]\n");
173	  printf("       apctl cycle [count] [timeout_ms]\n");
174	}
175	
176	/****************************************************************************
177	 * Public Functions
178	 ****************************************************************************/
179	
180	int main(int argc, char *argv[])
181	{
182	  uint32_t timeout;
183	  uint32_t count;
184	  uint32_t i;
185	  int ret = -EINVAL;
186	
187	  if (argc < 2)
188	    {
189	      apctl_usage();
190	      return 1;
191	    }
192	
193	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
194	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
195	
196	  if (strcmp(argv[1], "start") == 0)
197	    {
198	      ret = bk7258_ap_start(timeout);
199	    }
200	  else if (strcmp(argv[1], "stop") == 0)
201	    {
202	      ret = bk7258_ap_stop(timeout);
203	    }
204	  else if (strcmp(argv[1], "restart") == 0)
205	    {
206	      ret = bk7258_ap_restart(timeout);
207	    }
208	  else if (strcmp(argv[1], "status") == 0)
209	    {
210	      apctl_status();
211	      return 0;
212	    }
213	  else if (strcmp(argv[1], "cycle") == 0)
214	    {
215	      count = apctl_u32(argc > 2 ? argv[2] : NULL, 3);
216	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
217	                          BK7258_AP_DEFAULT_TIMEOUT_MS);
218	
219	      for (i = 0; i < count; i++)
220	        {
221	          ret = bk7258_ap_start(timeout);
222	          if (ret < 0)
223	            {
224	              break;
225	            }
226	
227	          apctl_status();
228	          ret = bk7258_ap_stop(timeout);
229	          if (ret < 0)
230	            {
231	              break;
232	            }
233	        }
234	    }
235	  else
236	    {
237	      apctl_usage();
238	      return 1;
239	    }
240	
241	  apctl_status();
242	  if (ret < 0)
243	    {
244	      fprintf(stderr, "apctl: %s failed: %d\n", argv[1], ret);
245	      return 1;
246	    }
247	
248	  return 0;
249	}
