1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/common/bk7258_irq.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Beken BK7258 (T5-AI, Cortex-M33) NVIC interrupt support for NuttX A1.
7	 *
8	 * Standard Cortex-M NVIC glue, modelled on nuttx/arch/arm/src/mps/mps_irq.c.
9	 * Provides up_irqinitialize() / up_enable_irq() / up_disable_irq() /
10	 * up_prioritize_irq() / arm_ack_irq() that the common armv8-m dispatch
11	 * code (arm_doirq.c, arm_exception.S) expects.  The BK7258 exposes 64
12	 * external IRQs (NR_IRQS=80 -> vector slots [16..79]); the chip-provided
13	 * vector table (bk7258_vectors.c) routes slots [2..3] through the
14	 * diagnostic bk7258_hardfault_handler and all other exceptions/IRQs through
15	 * exception_common.  Slots [64]/[65] hold boot magic in flash and are
16	 * runtime-repaired to exception_common via arm_ramvec_attach after VTOR
17	 * switches to RAM.  Once up_irqinitialize() runs, irq_attach()/
18	 * irq_dispatch() work normally.
19	 *
20	 * System-exception IRQ numbers use the canonical arm_m names from nvic.h
21	 * (NVIC_IRQ_HARDFAULT, NVIC_IRQ_SVCALL, NVIC_IRQ_PENDSV, ...) which equal
22	 * the BK7258_IRQ_* values in chip/include/irq.h.
23	 ****************************************************************************/
24	
25	/****************************************************************************
26	 * Included Files
27	 ****************************************************************************/
28	
29	#include <nuttx/config.h>
30	
31	#include <stdint.h>
32	#include <assert.h>
33	#include <debug.h>
34	
35	#include <nuttx/arch.h>
36	#include <arch/irq.h>
37	#include <arch/barriers.h>
38	
39	#include "ram_vectors.h"
40	#include "arm_internal.h"
41	#include "nvic.h"
42	
43	#include "bk7258_sdk_irq.h"
44	
45	/****************************************************************************
46	 * Pre-processor Definitions
47	 ****************************************************************************/
48	
49	/* NVIC enable/clear register bank stride. */
50	
51	#define NVIC_ENA_OFFSET         (0)
52	#define NVIC_CLRENA_OFFSET      (NVIC_IRQ0_31_CLEAR - NVIC_IRQ0_31_ENABLE)
53	
54	/* Default priority packed four-per-register (one stroke for all 4 slots). */
55	
56	#define DEFPRIORITY32           (NVIC_SYSH_PRIORITY_DEFAULT << 24 | \
57	                                 NVIC_SYSH_PRIORITY_DEFAULT << 16 | \
58	                                 NVIC_SYSH_PRIORITY_DEFAULT << 8  | \
59	                                 NVIC_SYSH_PRIORITY_DEFAULT)
60	
61	/****************************************************************************
62	 * Private Functions
63	 ****************************************************************************/
64	
65	/****************************************************************************
66	 * Name: bk7258_prioritize_syscall
67	 *
68	 * Description:
69	 *   Set the priority of the SVCall exception (system handler 11).  Needed
70	 *   internally even when CONFIG_ARCH_IRQPRIO is off.
71	 *
72	 ****************************************************************************/
73	
74	static inline void bk7258_prioritize_syscall(int priority)
75	{
76	  uint32_t regval;
77	
78	  regval  = getreg32(NVIC_SYSH8_11_PRIORITY);
79	  regval &= ~NVIC_SYSH_PRIORITY_PR11_MASK;
80	  regval |= (priority << NVIC_SYSH_PRIORITY_PR11_SHIFT);
81	  putreg32(regval, NVIC_SYSH8_11_PRIORITY);
82	}
83	
84	/****************************************************************************
85	 * Public Functions
86	 ****************************************************************************/
87	
88	/****************************************************************************
89	 * Name: bk7258_clear_pending_irq
90	 *
91	 * Description:
92	 *   Clear one pending external NVIC line using the same logical IRQ numbering
93	 *   as irq_attach() and up_enable_irq().
94	 *
95	 ****************************************************************************/
96	
97	void bk7258_clear_pending_irq(int irq)
98	{
99	  unsigned int external;
100	
101	  DEBUGASSERT(irq >= BK7258_IRQ_FIRST && irq < NR_IRQS);
102	
103	  if (irq < BK7258_IRQ_FIRST || irq >= NR_IRQS)
104	    {
105	      return;
106	    }
107	
108	  external = (unsigned int)(irq - BK7258_IRQ_FIRST);
109	  putreg32(1u << (external & 0x1f), NVIC_IRQ_CLRPEND(external));
110	  UP_DSB();
111	  UP_ISB();
112	}
113	
114	/****************************************************************************
115	 * Name: up_prioritize_irq
116	 *
117	 * Description:
118	 *   Set the priority of an IRQ.
119	 *
120	 ****************************************************************************/
121	
122	int up_prioritize_irq(int irq, int priority)
123	{
124	  uint32_t regaddr;
125	  uint32_t regval;
126	  int shift;
127	
128	  DEBUGASSERT(irq >= 0 && irq < NR_IRQS &&
129	              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);
130	
131	  if (irq < 16)
132	    {
133	      /* NVIC_SYSH_PRIORITY() maps {0..15} to one of the priority registers
134	       * (0-3 are invalid as raw indices; they are remapped internally).
135	       */
136	
137	      regaddr = NVIC_SYSH_PRIORITY(irq);
138	      irq    -= 4;
139	    }
140	  else
141	    {
142	      /* NVIC_IRQ_PRIORITY() maps {0..} to the external priority registers. */
143	
144	      irq    -= 16;
145	      regaddr = NVIC_IRQ_PRIORITY(irq);
146	    }
147	
148	  regval  = getreg32(regaddr);
149	  shift   = ((irq & 3) << 3);
150	  regval &= ~(0xff << shift);
151	  regval |= (priority << shift);
152	  putreg32(regval, regaddr);
153	
154	  return OK;
155	}
156	
157	/****************************************************************************
158	 * Name: up_irqinitialize
159	 *
160	 * Description:
161	 *   Bring the NVIC up to a known, ready state.  Called from up_initialize().
162	 *
163	 ****************************************************************************/
164	
165	void up_irqinitialize(void)
166	{
167	  uint32_t regaddr;
168	  int num_priority_registers;
169	  int i;
170	
171	  /* Step 1: Disable all 64 external NVIC lines.  BK7258_EXTERNAL_IRQS
172	   * is used for the loop bound; this clears banks starting at external
173	   * IRQ 0 and 32.
174	   */
175	
176	  for (i = 0; i < BK7258_EXTERNAL_IRQS; i += 32)
177	    {
178	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
179	    }
180	
181	  /* Step 2: Point VTOR at our flash-resident vector table (also set in
182	   * __start; redundant here but deterministic).
183	   */
184	
185	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
186	
187	  /* Step 3: Explicit barrier after the VTOR write. */
188	
189	  UP_DSB();
190	  UP_ISB();
191	
192	#ifdef CONFIG_ARCH_RAMVECTORS
193	
194	  /* Step 4: Copy all 80 entries from flash to RAM and switch VTOR to
195	   * g_ram_vectors.  arm_ramvec_initialize() does both.
196	   */
197	
198	  arm_ramvec_initialize();
199	
200	  /* Step 5: Repair the two boot-magic slots (64/65) that the bootloader
201	   * requires but that NuttX must route through exception_common.  These
202	   * are logical IRQ/vector slots 64 and 65.  Do not use ordinary
203	   * irq_attach() for this repair.
204	   */
205	
206	  {
207	    int ret0;
208	    int ret1;
209	
210	    ret0 = arm_ramvec_attach(BK7258_IRQ_ETHERNET, exception_common);
211	    ret1 = arm_ramvec_attach(BK7258_IRQ_SCALE0, exception_common);
212	
213	    /* Step 6: Capture/check both return values.  A failure must not
214	     * continue to final IRQ unmasking.  Both calls must be made before
215	     * the combined failure decision.
216	     */
217	
218	    if (ret0 < 0 || ret1 < 0)
219	      {
220	        PANIC();
221	      }
222	
223	    /* Step 7: Barrier after the two RAM slot writes. */
224	
225	    UP_DSB();
226	    UP_ISB();
227	
228	    /* Step 8: Debug assertions before unmasking. */
229	
230	    DEBUGASSERT(getreg32(NVIC_VECTAB) == (uint32_t)g_ram_vectors);
231	    DEBUGASSERT((uintptr_t)g_ram_vectors[BK7258_IRQ_ETHERNET] ==
232	                ((uintptr_t)exception_common | 1u));
233	    DEBUGASSERT((uintptr_t)g_ram_vectors[BK7258_IRQ_SCALE0] ==
234	                ((uintptr_t)exception_common | 1u));
235	  }
236	
237	#endif /* CONFIG_ARCH_RAMVECTORS */
238	
239	  /* Step 9: Continue the existing default priorities, system-handler
240	   * attachments, IRQ stack coloring, and final up_irq_enable().
241	   */
242	
243	  /* Default-prioritise the system exceptions. */
244	
245	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
246	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
247	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
248	
249	  /* The NVIC ICTR register (bits 0-4) holds (number of IRQ lines / 32) - 1,
250	   * which also tells us how many priority registers to default-fill.
251	   */
252	
253	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
254	
255	  regaddr = NVIC_IRQ0_3_PRIORITY;
256	  while (num_priority_registers--)
257	    {
258	      putreg32(DEFPRIORITY32, regaddr);
259	      regaddr += 4;
260	    }
261	
262	  /* Attach the SVCall and HardFault handlers used by the scheduler. */
263	
264	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
265	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
266	
267	  /* PendSV runs at the lowest priority so it never preempts device IRQs. */
268	
269	  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
270	  bk7258_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
271	
272	  /* Enable the MemManage fault if the MPU is in use. */
273	
274	#ifdef CONFIG_ARM_MPU
275	  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
276	  up_enable_irq(NVIC_IRQ_MEMFAULT);
277	#endif
278	
279	#ifndef CONFIG_SUPPRESS_INTERRUPTS
280	
281	  /* Colour the interrupt stack (writes a sentinel pattern) and unmask IRQs. */
282	
283	  arm_color_intstack();
284	  up_irq_enable();
285	#endif
286	}
