288	/****************************************************************************
289	 * Name: bk7258_irqinfo
290	 *
291	 * Description:
292	 *   Map a NuttX IRQ number to the (register, bit) pair that enables/disables
293	 *   it in the NVIC, honouring the enable/clear bank offset for external IRQs
294	 *   and the SYSHCON/SYSTICK control bits for the handful of manageable
295	 *   system exceptions.
296	 *
297	 ****************************************************************************/
298	
299	static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
300	                          uintptr_t offset)
301	{
302	  int n;
303	
304	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
305	
306	  /* External device interrupt? */
307	
308	  if (irq >= BK7258_IRQ_FIRST)
309	    {
310	      n        = irq - BK7258_IRQ_FIRST;
311	      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
312	      *bit     = (uint32_t)0x1 << (n & 0x1f);
313	    }
314	
315	  /* Processor exception -- only a few can be enabled/disabled. */
316	
317	  else
318	    {
319	      *regaddr = NVIC_SYSHCON;
320	      if (irq == NVIC_IRQ_MEMFAULT)
321	        {
322	          *bit = NVIC_SYSHCON_MEMFAULTENA;
323	        }
324	      else if (irq == NVIC_IRQ_BUSFAULT)
325	        {
326	          *bit = NVIC_SYSHCON_BUSFAULTENA;
327	        }
328	      else if (irq == NVIC_IRQ_USAGEFAULT)
329	        {
330	          *bit = NVIC_SYSHCON_USGFAULTENA;
331	        }
332	      else if (irq == NVIC_IRQ_SYSTICK)
333	        {
334	          *regaddr = NVIC_SYSTICK_CTRL;
335	          *bit = NVIC_SYSTICK_CTRL_ENABLE;
336	        }
337	      else
338	        {
339	          return -EINVAL;  /* Invalid or unsupported exception */
340	        }
341	    }
342	
343	  return OK;
344	}
345	
346	/****************************************************************************
347	 * Name: up_disable_irq
348	 *
349	 ****************************************************************************/
350	
351	void up_disable_irq(int irq)
352	{
353	  uintptr_t regaddr;
354	  uint32_t  regval;
355	  uint32_t  bit;
356	
357	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_CLRENA_OFFSET) == 0)
358	    {
359	      if (irq >= BK7258_IRQ_FIRST)
360	        {
361	          /* External: write 1 to the Clear-Enable bank bit. */
362	
363	          putreg32(bit, regaddr);
364	        }
365	      else
366	        {
367	          /* System exception: clear the SYSHCON / SYSTICK bit. */
368	
369	          regval  = getreg32(regaddr);
370	          regval &= ~bit;
371	          putreg32(regval, regaddr);
372	        }
373	    }
374	}
375	
376	/****************************************************************************
377	 * Name: up_enable_irq
378	 *
379	 ****************************************************************************/
380	
381	void up_enable_irq(int irq)
382	{
383	  uintptr_t regaddr;
384	  uint32_t  regval;
385	  uint32_t  bit;
386	
387	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_ENA_OFFSET) == 0)
388	    {
389	      if (irq >= BK7258_IRQ_FIRST)
390	        {
391	          /* External: write 1 to the Set-Enable bank bit. */
392	
393	          putreg32(bit, regaddr);
394	        }
395	      else
396	        {
397	          /* System exception: set the SYSHCON / SYSTICK bit. */
398	
399	          regval  = getreg32(regaddr);
400	          regval |= bit;
401	          putreg32(regval, regaddr);
402	        }
403	    }
404	}
