11	static mailbox_data_t	mailbox_buff[MBOX_CHNL_NUM][TX_BOX_NUM];
12	static mailbox_callback_t  mailbox_callback[MBOX_CHNL_NUM] = {0};
13	static uint8_t	mailbox_tx_box[MBOX_CHNL_NUM] = {0};
