15	static void mbox0_rx_isr(mbox0_message_t *msg)
16	{
17		mailbox_data_t data;
18		u32 chnl = msg->src_cpu;
19	
20		if(chnl >= MBOX_CHNL_NUM)
21			return;
22	
23		if(msg->data[1] == sizeof(data))
24		{
25	#if CONFIG_CACHE_ENABLE
26		  	extern void flush_dcache(void *va, long size);
27			flush_dcache((void *)msg->data[0], sizeof(data));
28	#endif
29			memcpy(&data, (u8 *)msg->data[0], sizeof(data));
30		}
31		else
32		{
33			return;
34		}
35	
36		if(mailbox_callback[chnl] != NULL)
37			mailbox_callback[chnl](&data);
38	}
