28	typedef struct
29	{
30		volatile u8		tx_state;	/* physical channel tx state. */
31		u8		tx_seq;				/* physical channel tx sequence. */
32		u8		tx_log_chnl;		/* logical channel. */ /* bit7~bit4: dst/src CPU_ID, bit3~bit0: log_chnl_idx. */
33		u8		tx_hdr_cmd;
34		u32		rx_fault_cnt;
35		u32		tx_fault_cnt;
36	} mb_phy_chnl_cb_t;
