38	
39	#define CHNL_CTRL_MASK			0xF
40	/*
41	 *  there are 2 boxes in one MAILBOXn HW,
42	 *  but no way to know which box this msg is from in current mailbox_driver design.
43	 *  use the CHNL_CTRL_ACK_BOX bit in the msg hdr.ctrl to distinguish where it is from.
44	 *  when CHNL_CTRL_ACK_BOX is set, it means from ack box ( MAILBOXn_BOX1 ).
45	 */
46	#define CHNL_CTRL_ACK_BOX		0x01
47	
48	#define CHNL_CTRL_SYNC_TX		0x02
49	#define CHNL_CTRL_RESET			0x04
