546	/* =====================      logical channel APIs      ==================*/
547	/*
548	  * init logical chnanel module.
549	  * return:
550	  *     succeed: BK_OK;
551	  *     failed  : fail code.
552	  *
553	  */
554	bk_err_t mb_chnl_init(void)
555	{
556		bk_err_t		ret_code;
557		int				i, j;
558	
559		mb_log_chnl_cb_t * log_chnl_cb_x;
560	
561		if(mb_chnnl_init_ok)
562		{
563			return BK_OK;
564		}
565	
566		memset(&phy_chnl_x_cb, 0, sizeof(phy_chnl_x_cb));
567		for(i = 0; i < PHY_CHNL_NUM; i++)
568		{
569			phy_chnl_x_cb[i].tx_state = CHNL_STATE_IDLE;
570	
571			log_chnl_cb_x = (mb_log_chnl_cb_t *)(phy_chnl_log_chnl_list[i]);
572	
573			memset(log_chnl_cb_x, 0, sizeof(mb_log_chnl_cb_t) * phy_chnl_log_chnl_num[i]);
574	
575			for(j = 0; j < phy_chnl_log_chnl_num[i]; j++)
576			{
577				log_chnl_cb_x[j].tx_state = CHNL_STATE_IDLE;
578			}
579		}
580	
581		ret_code = bk_mailbox_init();
582		if(ret_code != BK_OK)
583		{
584			return ret_code;
585		}
586	
587		mailbox_endpoint_t    dst_cpu;
588	
589		for(i = 0; i < PHY_CHNL_NUM; i++)
590		{
591			dst_cpu = (mailbox_endpoint_t)(i);  // dst_cpu_id;
592	
593			bk_mailbox_recv_callback_register(dst_cpu, SELF_CPU, mb_phy_chnl_rx_isr);
594		}
595	
596		mb_phy_chnl_reset(0);
597	
598		mb_chnnl_init_ok = 1;
599	
600		return BK_OK;
601	}
