603	/*
604	  * open logical chnanel.
605	  * input:
606	  *     log_chnl  : logical channel id to open.
607	  *     callback_param : param passsed to all callbacks.
608	  * return:
609	  *     succeed: BK_OK;
610	  *     failed  : fail code.
611	  *
612	  */
613	bk_err_t mb_chnl_open(u8 log_chnl, void * callback_param)
614	{
615		if(!mb_chnnl_init_ok)	/* if driver is not initialized. */
616		{
617			bk_err_t		ret_code;
618	
619			ret_code = mb_chnl_init();
620	
621			if(ret_code != BK_OK)
622			{
623				return ret_code;
624			}
625		}
626	
627		u8		phy_chnl_idx = GET_DST_CPU_ID(log_chnl);   // = DST_CPU_ID;
628		u8		log_chnl_idx = GET_LOG_CHNL_ID(log_chnl);
629	
630		mb_log_chnl_cb_t * log_chnl_cb_x;
631	
632		if(SELF_CPU != GET_SRC_CPU_ID(log_chnl))
633			return BK_ERR_PARAM;
634	
635		if(SELF_CPU == phy_chnl_idx)  // transferred to self.
636			return BK_ERR_PARAM;
637	
638		if(phy_chnl_idx >= PHY_CHNL_NUM)
639			return BK_ERR_PARAM;
640	
641		log_chnl_cb_x = (mb_log_chnl_cb_t *)(phy_chnl_log_chnl_list[phy_chnl_idx]);
642	
643		if(log_chnl_idx >= phy_chnl_log_chnl_num[phy_chnl_idx])
644			return BK_ERR_PARAM;
645	
646		if(log_chnl_cb_x[log_chnl_idx].in_used)
647			return BK_ERR_OPEN;
648	
649		log_chnl_cb_x[log_chnl_idx].in_used = 1;		/* chnl in used. */
650		log_chnl_cb_x[log_chnl_idx].isr_param = callback_param;
651	
652		return BK_OK;
653	}
