54	               "Stage B gate: SDK source 0..63 must map to IRQ 16..79");
55	_Static_assert(BK7258_SDK_IRQ_PRIORITY_BITS == 3,
56	               "Stage B gate: STAR NVIC implements three priority bits");
57	_Static_assert(INT_SRC_LCD == 27,
58	               "Stage B gate: LCD priority exception must remain source 27");
59	#ifdef CONFIG_BK7258_GPIO_IRQ_TEST
