72	/****************************************************************************
73	 * Private Data
74	 ****************************************************************************/
75	
76	static spinlock_t g_bk7258_sdk_irq_lock = SP_UNLOCKED;
77	static int_group_isr_t g_bk7258_sdk_irq_handlers[BK7258_SDK_IRQ_COUNT];
78	#ifdef CONFIG_BK7258_GPIO_IRQ_TEST
79	static volatile uint32_t g_bk7258_sdk_irq_gpio_dispatch_counts[
80	  BK7258_SDK_IRQ_GPIO_SOURCE_COUNT];
81	#endif
