83	/****************************************************************************
84	 * Private Functions
85	 ****************************************************************************/
86	
87	static int bk7258_sdk_source_to_irq(icu_int_src_t source)
88	{
89	  unsigned int index = (unsigned int)source;
90	
91	  if (index >= BK7258_SDK_IRQ_COUNT)
92	    {
93	      return -1;
94	    }
95	
96	  return BK7258_SDK_IRQ_FIRST + (int)index;
97	}
98	
99	static int bk7258_sdk_irq_encode_priority(uint32_t priority)
100	{
101	  if (priority > BK7258_SDK_IRQ_PRIORITY_MAX)
102	    {
103	      return -1;
104	    }
105	
106	#ifndef CONFIG_ARCH_HIPRI_INTERRUPT
107	  /* The common ARMv8-M dispatcher is not re-entrant in this configuration.
108	   * Keep SDK device IRQs at the same logical priority as SysTick so neither
109	   * can preempt the other while arm_doirq owns a TCB exception context.
110	   */
111	
112	  priority = BK7258_SDK_IRQ_DEFAULT_PRIORITY;
113	#endif
114	
115	  return (int)(priority << BK7258_SDK_IRQ_PRIORITY_SHIFT);
116	}
117	
118	static uint32_t bk7258_sdk_irq_default_priority(icu_int_src_t source)
119	{
120	  if (source == INT_SRC_LCD)
121	    {
122	      return BK7258_SDK_IRQ_LCD_PRIORITY;
123	    }
124	
125	  return BK7258_SDK_IRQ_DEFAULT_PRIORITY;
126	}
127	
128	static int bk7258_sdk_irq_dispatch(int irq, void *context, void *arg)
129	{
130	  unsigned int source;
131	  int_group_isr_t handler;
132	
133	  (void)context;
134	  (void)arg;
135	
136	  source = (unsigned int)(irq - BK7258_SDK_IRQ_FIRST);
137	  if (source >= BK7258_SDK_IRQ_COUNT)
138	    {
139	      return OK;
140	    }
141	
142	  handler = g_bk7258_sdk_irq_handlers[source];
143	
144	#ifdef CONFIG_BK7258_GPIO_IRQ_TEST
145	  if (source == BK7258_SDK_IRQ_GPIO_SECURE_SOURCE)
146	    {
147	      g_bk7258_sdk_irq_gpio_dispatch_counts[
148	        BK7258_SDK_IRQ_GPIO_SECURE_INDEX]++;
149	    }
150	  else if (source == BK7258_SDK_IRQ_GPIO_NONSECURE_SOURCE)
151	    {
152	      g_bk7258_sdk_irq_gpio_dispatch_counts[
153	        BK7258_SDK_IRQ_GPIO_NONSECURE_INDEX]++;
154	    }
155	#endif
156	
157	  if (handler != NULL)
158	    {
159	      handler();
160	    }
161	
162	  return OK;
163	}
