165	static bk_err_t
166	bk7258_sdk_irq_unregister_locked(unsigned int index, int irq)
167	{
168	  int ret;
169	
170	  up_disable_irq(irq);
171	  bk7258_clear_pending_irq(irq);
172	  g_bk7258_sdk_irq_handlers[index] = NULL;
173	  UP_DSB();
174	  UP_ISB();
175	
176	  ret = irq_detach(irq);
177	  return ret < 0 ? BK_FAIL : BK_OK;
178	}
179	
180	/****************************************************************************
181	 * Public Functions
182	 ****************************************************************************/
183	
184	bk_err_t bk_int_isr_register(icu_int_src_t source,
185	                             int_group_isr_t handler, void *arg)
186	{
187	  unsigned int index = (unsigned int)source;
188	  irqstate_t flags;
189	  bk_err_t result;
190	  int priority;
191	  int irq;
192	  int ret;
193	
194	  (void)arg; /* The CP CM33 SDK implementation also ignores this argument. */
195	
196	  irq = bk7258_sdk_source_to_irq(source);
197	  if (irq < 0)
198	    {
199	      return BK_ERR_INT_DEVICE_NONE;
200	    }
201	
202	  priority = bk7258_sdk_irq_encode_priority(
203	      bk7258_sdk_irq_default_priority(source));
204	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
205	
206	  /* Registration replaces the previous owner of this source.  Keep the
207	   * line disabled and non-pending until both NuttX dispatch state and
208	   * priority are complete.
209	   */
210	
211	  result = bk7258_sdk_irq_unregister_locked(index, irq);
212	  if (result != BK_OK)
213	    {
214	      goto out;
215	    }
216	
217	  ret = up_prioritize_irq(irq, priority);
218	  if (ret < 0)
219	    {
220	      result = BK_FAIL;
221	      goto out;
222	    }
223	
224	  /* A NULL SDK callback has the same net effect as the vendor CM33 path:
225	   * the previous callback is removed and the interrupt stays disabled.
226	   */
227	
228	  if (handler == NULL)
229	    {
230	      result = BK_OK;
231	      goto out;
232	    }
233	
234	  ret = irq_attach(irq, bk7258_sdk_irq_dispatch, NULL);
235	  if (ret < 0)
236	    {
237	      result = BK_FAIL;
238	      goto out;
239	    }
240	
241	  g_bk7258_sdk_irq_handlers[index] = handler;
242	  UP_DSB();
243	  UP_ISB();
244	  up_enable_irq(irq);
245	  result = BK_OK;
246	
247	out:
248	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
249	  return result;
250	}
251	
252	bk_err_t bk_int_isr_unregister(icu_int_src_t source)
253	{
254	  unsigned int index = (unsigned int)source;
255	  irqstate_t flags;
256	  bk_err_t result;
257	  int irq;
258	
259	  irq = bk7258_sdk_source_to_irq(source);
260	  if (irq < 0)
261	    {
262	      return BK_ERR_INT_DEVICE_NONE;
263	    }
264	
265	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
266	  result = bk7258_sdk_irq_unregister_locked(index, irq);
267	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
268	  return result;
269	}
