271	bk_err_t bk_int_set_priority(icu_int_src_t source, uint32_t priority)
272	{
273	  irqstate_t flags;
274	  bk_err_t result;
275	  int encoded;
276	  int irq;
277	
278	  irq = bk7258_sdk_source_to_irq(source);
279	  if (irq < 0)
280	    {
281	      return BK_ERR_INT_DEVICE_NONE;
282	    }
283	
284	  encoded = bk7258_sdk_irq_encode_priority(priority);
285	  if (encoded < 0)
