296	bk_err_t bk7258_sdk_irq_snapshot_handler(icu_int_src_t source,
297	                                         int_group_isr_t *handler)
298	{
299	  unsigned int index = (unsigned int)source;
300	  irqstate_t flags;
301	
302	  if (handler == NULL)
303	    {
304	      return BK_FAIL;
305	    }
306	
307	  if (bk7258_sdk_source_to_irq(source) < 0)
308	    {
309	      return BK_ERR_INT_DEVICE_NONE;
310	    }
311	
312	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
313	  *handler = g_bk7258_sdk_irq_handlers[index];
314	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
315	  return BK_OK;
316	}
