4	static int mbox0_hal_chn0_cfg_fifo(mbox0_hal_t* hal, uint8_t start, uint8_t len)
5	{
6		mbox0_hw_t * hw = hal->hw;
7	
8		if(hw == NULL)
9			return MBOX0_HAL_SW_NO_INIT;
10	
11		if((len > hal->fifo_size) || ((start + len) > hal->fifo_size))
12			return MBOX0_HAL_SW_FIFO_OVERFLOW;
13	
14		mbox0_ll_set_reg_0x10_fifo_start(hw, start);
15		mbox0_ll_set_reg_0x11_fifo_length(hw, len);
16		mbox0_ll_set_reg_0x11_chn_enable(hw, 1);
17	
18		return MBOX0_HAL_OK;
19	}
