162	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
163	{
164	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
165	  uint32_t elapsed;
166	  uint32_t event;
167	
168	  if (timeout_ms == 0)
169	    {
170	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
171	    }
172	
173	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
174	    {
175	      event = bk7258_ap_mbox_receive();
176	      if (event != BK7258_AP_EVENT_NONE)
177	        {
178	          state->last_event = event;
179	        }
180	
181	      __asm volatile ("dmb sy" ::: "memory");
182	      if (state->state == wanted)
183	        {
184	          return OK;
185	        }
186	
187	      if (state->state == BK7258_AP_STATE_FAILED)
188	        {
189	          return -EIO;
190	        }
191	
192	      nxsig_usleep(1000);
193	    }
194	
195	  return -ETIMEDOUT;
196	}
