198	static int bk7258_ap_start_locked(uint32_t timeout_ms)
199	{
200	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
201	  int ret;
202	
203	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
204	      (state->state == BK7258_AP_STATE_READY ||
205	       state->state == BK7258_AP_STATE_STARTING))
206	    {
207	      return -EBUSY;
208	    }
209	
210	  /* Hold CPU1 while replacing shared state and the boot address. */
211	
212	  sys_drv_set_cpu1_reset(0);
213	  __asm volatile ("dsb sy; isb sy" ::: "memory");
214	  bk7258_cpu2_force_reset();
215	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
216	  bk7258_ap_mbox_initialize();
217	  bk7258_ap_state_prepare();
218	
219	  /* Exact BK7258 CPU1 release order from the CP SDK. */
220	
221	  sys_drv_set_cpu1_pwr_dw(0);
222	  sys_drv_set_cpu1_rxevt_sel(1);
223	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
224	  __asm volatile ("dsb sy; isb sy" ::: "memory");
225	  sys_drv_set_cpu1_reset(1);
226	  __asm volatile ("dsb sy; sev" ::: "memory");
227	
228	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
229	  if (ret < 0)
230	    {
231	      sys_drv_set_cpu1_reset(0);
232	      __asm volatile ("dsb sy; isb sy" ::: "memory");
233	      bk7258_cpu2_force_reset();
234	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
235	      sys_drv_set_cpu1_pwr_dw(1);
236	
237	      if (state->state != BK7258_AP_STATE_FAILED)
238	        {
239	          state->error = BK7258_AP_ERROR_TIMEOUT;
240	        }
241	
242	      state->command = BK7258_AP_COMMAND_NONE;
243	      state->state = BK7258_AP_STATE_FAILED;
244	      state->last_event = BK7258_AP_EVENT_FAILED;
245	      __asm volatile ("dmb sy" ::: "memory");
246	    }
247	
248	  return ret;
249	}
