251	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
252	{
253	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
254	  int ret = OK;
255	
256	  if (state->state == BK7258_AP_STATE_READY ||
257	      state->state == BK7258_AP_STATE_STARTING)
258	    {
259	      state->command = BK7258_AP_COMMAND_STOP;
260	      __asm volatile ("dmb sy" ::: "memory");
261	      bk7258_ap_mbox_send(BK7258_AP_EVENT_STOP);
262	      ret = bk7258_ap_wait(BK7258_AP_STATE_STOPPED, timeout_ms);
263	    }
264	
265	  /* A timeout still ends in a deterministic forced stop of both AP cores. */
266	
267	  sys_drv_set_cpu1_reset(0);
268	  __asm volatile ("dsb sy; isb sy" ::: "memory");
269	  bk7258_cpu2_force_reset();
270	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
271	  sys_drv_set_cpu1_pwr_dw(1);
272	
273	  if (ret < 0 && state->state != BK7258_AP_STATE_FAILED)
274	    {
275	      state->error = BK7258_AP_ERROR_TIMEOUT;
276	    }
277	
278	  state->command = BK7258_AP_COMMAND_NONE;
279	  state->state = BK7258_AP_STATE_STOPPED;
280	  state->last_event = BK7258_AP_EVENT_STOPPED;
281	  __asm volatile ("dmb sy" ::: "memory");
282	  return ret;
283	}
